PrologProcedure:
#Region Seed FX rates — 1 unit of currency in the reporting currency (GBP). Order: Period, Version, Currency, FX Rate Type, Measure
# Seeded for EVERY leaf version — FX is market data, not a planning assumption,
# so all versions (incl. the calculated Forecast) share the same rates.
cCube = 'WFP FX Rates';
cPer  = 'WFP Period';
cVer  = 'WFP Version';
nPcount = DIMSIZ( cPer );
nVcount = DIMSIZ( cVer );

vC = 'GBP;1~USD;0.79~NZD;0.47~Reporting;1~';

WHILE( SCAN( '~', vC ) > 1 );
   nS = SCAN( '~', vC );
   vRec = SUBST( vC, 1, nS - 1 ) | ';';
   vC = SUBST( vC, nS + 1, LONG( vC ) - nS );

   nS = SCAN(';',vRec); vCur = SUBST(vRec,1,nS-1); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nRate = NUMBR(SUBST(vRec,1,nS-1));

   nP = 1;
   WHILE( nP <= nPcount );
      vPer = DIMNM( cPer, nP );
      IF( DTYPE( cPer, vPer ) @= 'N' );
         nV = 1;
         WHILE( nV <= nVcount );
            vVer = DIMNM( cVer, nV );
            IF( DTYPE( cVer, vVer ) @= 'N' );
               CellPutN( nRate, cCube, vPer, vVer, vCur, 'Average', 'Rate' );
               CellPutN( nRate, cCube, vPer, vVer, vCur, 'Closing', 'Rate' );
            ENDIF;
            nV = nV + 1;
         END;
      ENDIF;
      nP = nP + 1;
   END;
END;
